from 写入第二遍 import add
add('17_001',1,'16:9，满幅抽象过场，黑色占据画面中央，上下边缘灰白渐变；固定构图。','中央黑场保持，上下灰白边缘先向黑场收窄，再在镜尾退成一道薄亮；没有人物进入，画外先听到青一次压不住的呼吸。','纯黑图形底场，上下边缘由灰白柔和渐变到黑色。','非实景过场，无物理光源变化。','远处低频余响渐轻，一次近处急喘先进入。',kind='state',phase='state',node={'场景阶段':'原作时间省略后的转场'},meaning='原作独立渐变过场保留，不制造新人物或新的原作攻击。',mode='graphic')
add('17_002',3,'16:9，青居中正面中景，从额头到腰下，手臂分在两侧；镜头随一次较深呼吸向下移少许，落幅含紧握的手、起伏腰腹与头肩。','青单眼闭紧，另一眼仍盯着画外武士消失的尘雾，嘴张开急喘；她的双拳先绷紧，胸肩被一口气顶起，再跟着呼气落下。发梢贴着手背晃过，汗从额角和腹侧滑下，她强行把闭着的眼睁开，双腿仍撑住站位。','灰绿石铺地面有几道细裂纹，远端米灰薄尘压成浅色层。','上方云天冷白漫射，烟囱残基侧稍亮，石地返少量中性光。','急喘有一短一长，衣料随胸肩起伏轻响，细灰落石声在远处。',phase='reaction',node={'青.阶段':'喘息中持续盯住尘雾','青.接触':'双脚站稳石铺平台'},card={'opening':'青已经疲惫，注意仍未从对手方向移开。','beats':['单眼闭紧、握拳急喘','强行睁眼，把呼吸压回去'],'coupling':'疲态与警觉同时在身体上成立。','landing':'站位仍稳，继续看尘雾。'})
add('18_001',9,'16:9，从青背后略低机位全景，青位于画面右侧，双腿分开；两块破石在近侧左右边缘，尘雾占左后景。镜头缓慢横移到她右肩后，落幅仍见青与整片尘雾之间的空地。','青把呼吸压低，头先向尘雾最浓的位置偏，接着沿烟尘边缘扫向另一端；原本攥紧的手慢慢松出一条缝，肩膀却没有落下。尘层向外摊开，始终没有清楚的人影走出；她把一只脚向后挪半步，保持身体面对尘雾，头停住等下一声动静。','前侧灰绿石铺地面向烟尘延伸，近侧破裂石体与远端低矮残墙分出层次，铅蓝天空位于尘层上方。','上方冷白云天透过米灰尘层，烟囱残基侧稍亮；尘层内部较暗。','青逐渐收轻的呼吸，砂粒偶尔落地，远处沉闷余响迟迟不散。',ja=['あれだけで倒せるはずがない。どうして姿を見せないの…？','罠なの？'],tone='内心先分析再生疑，嘴保持闭合，只以呼吸参与。',kind='mixed',phase='state',node={'青.阶段':'观察烟尘并怀疑陷阱','武士.阶段':'尘雾中暂未现身'},card={'opening':'青喘息后等待攻击结果。','beats':['扫过整片尘雾仍不见人','手微松、脚后移，重新拉紧戒备'],'coupling':'环境没有回应，使她从等结果转成防埋伏。','landing':'身体对着尘雾，仍在等待。'})
